        drawWarpSpacePulse,
        warpSpacePaletteAt,
        warpSpaceFlowMix,
        warpSpacePingPong,
        warpSpacePanelCss,
        warpSpacePanelRgb,
        warpSpaceSeamCss,
        warpSpaceAccentCss,
        warpSpaceRingRgb,
        warpSpaceSeedFor,
        warpSpaceNextSeed,
        warpSpaceDirectionFor,
        warpSpaceDirectionRamp,
        warpSpaceTier,
        warpSpaceTierParams,
        warpSpaceCycleConfig,
        warpSpaceCycleAt,
        WARP_SPACE_RANDOM,
        warpSpaceRandomCycleAt,
        warpSpaceRandomCyclePlan,
        warpSpaceCellField,
        drawSpaceDissolve,
        WARP_SPACE_TRANSITIONS,
        warpSpaceTransitionIds,
        warpSpaceTransitionFor,
        drawSpaceWipe,
        drawSpaceTransition,
        WARP_SPACE_SHIP_SPECS,
        warpSpaceShipSpec,
        warpSpaceShipSize,
        paintShipRear,
        drawWarpShip,
        warpSpaceShipRollFor,
        warpSpaceCellGrid,
        warpSpaceDeviceProfile,
        WARP_SPACE_CELL_PRESETS,
        WARP_SPACE_DISSOLVE,
        warpSpaceDissolveBudget,
        warpSpaceDissolveFrameCap,
        WARP_SPACE_ASTEROIDS,
        WARP_SPACE_ASTEROID_SLOTS,
        warpSpaceAsteroidIds,
        warpSpaceAsteroidSizeOf,
        warpSpaceAsteroidField,
        warpSpaceAsteroidRadius,
        warpSpaceAsteroidDepthAt,
        drawWarpSpaceAsteroids,
        warpSpaceQuadArea,
        warpSpacePanelVisible,
        WARP_SPACE_ANOMALIES,
        warpSpaceAnomalyPlan,
        warpSpaceAnomalyPoint,
        warpSpaceAnomalyVariantIds,
        warpSpaceAnomalyVariantFor,
        warpSpaceAnomalySpec,
        WARP_SPACE_ANOMALY_VARIANTS,
        drawWarpSpaceAnomaly,
        warpSpaceEffectLevel,
